def extend(page):
    from .analytics_ui import CSS as analytics_css, SECTION as analytics_section, JS as analytics_js
    sections=analytics_section+SECTIONS[SECTIONS.index('<section id="monitorsView"'):]
    page=page.replace('</style>',CSS+analytics_css+'</style>',1)
    nav=''.join(f'<a href="#{key}" data-view="{key}"><span class="nav-icon" aria-hidden="true">{icon}</span>{title}</a>' for key,icon,title in [('analysis','⌁','搜索分析'),('monitors','◉','关键词监测'),('api','⌘','API 中心')])
    page=page.replace('<a href="#whale" data-view="whale">',nav+'<a href="#whale" data-view="whale">',1)
    page=page.replace('<footer class="foot" id="updated">',sections+'<footer class="foot" id="updated">',1)
    page=page.replace("['overview','create','tasks','results','whale','settings']","['overview','create','tasks','results','whale','settings','analysis','monitors','api']")
    page=page.replace("settings:'数据偏好'}[view]","settings:'数据偏好',analysis:'搜索分析',monitors:'关键词监测',api:'API 中心',maps:'Google Maps'}[view]")
    page=page.replace("settings:'了解数据范围与可选采集内容'}[view]","settings:'了解数据范围与可选采集内容',analysis:'从历史结果中找到变化',monitors:'跟踪关键词与竞品的真实排名',api:'把搜索数据接入你的产品',maps:'实时查询地点与商家'}[view]")
    page=page.replace('const jobs=[loadSettings()];',"const jobs=[loadSettings()];if(productViews.includes(current))jobs.push(loadProductView());")
    page=page.replace("window.addEventListener('hashchange',showView);showView();setInterval(refreshView,10000);",JS+analytics_js+"\nwindow.addEventListener('hashchange',showView);showView();setInterval(refreshView,10000);")
    page=page.replace("'每 10 秒刷新 / 最近读取 '+new Date()", "(current==='analysis'?'报告按需更新 / 页面检查 ':'每 10 秒刷新 / 最近读取 ')+new Date()")
    from .workbench_ui import extend as refine_ui
    from .data_capability_ui import extend as capability_ui
    from .insights_ui import extend as insights_ui
    from .google_local_ui import extend as local_ui
    from .quick_request_ui import extend as quick_ui
    from .component_ui import extend as component_ui
    from .workspace_guides_ui import extend as workspace_guides_ui
    page = component_ui(quick_ui(local_ui(insights_ui(capability_ui(refine_ui(page))))))
    from .google_analysis_ui import extend as google_analysis_ui
    return google_analysis_ui(workspace_guides_ui(page))

